typedef struct Node {
    int value;
    struct Node *next;
} Node;

void list_push(Node **head, int value) {
    Node *node = malloc(sizeof(Node));
    node->value = value;
    node->next = *head;
    *head = node;
}

int list_pop(Node **head) {
    if (!*head) return -1;
    Node *tmp = *head;
    int val = tmp->value;
    *head = tmp->next;
    free(tmp);
    return val;
}

void list_free(Node **head) {
    while (*head) list_pop(head);
}

