#include <string.h>

#define HMAP_SIZE 256

typedef struct { char *key; int value; int used; } Bucket;

static Bucket _hmap[HMAP_SIZE];

static unsigned int _hash(const char *s) {
    unsigned int h = 5381;
    while (*s) h = ((h << 5) + h) + (unsigned char)*s++;
    return h % HMAP_SIZE;
}

void hmap_set(const char *key, int value) {
    unsigned int i = _hash(key);
    while (_hmap[i].used && strcmp(_hmap[i].key, key) != 0)
        i = (i + 1) % HMAP_SIZE;
    if (!_hmap[i].used) _hmap[i].key = strdup(key);
    _hmap[i].value = value;
    _hmap[i].used = 1;
}

int hmap_get(const char *key, int def) {
    unsigned int i = _hash(key);
    while (_hmap[i].used) {
        if (strcmp(_hmap[i].key, key) == 0) return _hmap[i].value;
        i = (i + 1) % HMAP_SIZE;
    }
    return def;
}

void hmap_free(void) {
    for (int i = 0; i < HMAP_SIZE; i++)
        if (_hmap[i].used) { free(_hmap[i].key); _hmap[i].used = 0; }
}

class EventEmitter {
  constructor() {
    this._events = {};
  }

  on(event, listener) {
    (this._events[event] = this._events[event] || []).push(listener);
    return this;
  }

  off(event, listener) {
    if (!this._events[event]) return this;
    this._events[event] = this._events[event].filter(l => l !== listener && l._orig !== listener);
    return this;
  }

  emit(event, ...args) {
    (this._events[event] || []).slice().forEach(l => l(...args));
    return this;
  }

  once(event, listener) {
    const wrapper = (...args) => { this.off(event, wrapper); listener(...args); };
    wrapper._orig = listener;
    return this.on(event, wrapper);
  }
}

