char **str_split(const char *str, char delim, int *count) {
    int n = 1;
    for (const char *p = str; *p; p++) if (*p == delim) n++;
    char **parts = malloc(n * sizeof(char *));
    *count = 0;
    const char *start = str;
    for (const char *p = str; ; p++) {
        if (*p == delim || *p == '\0') {
            int len = p - start;
            parts[(*count)++] = strndup(start, len);
            if (*p == '\0') break;
            start = p + 1;
        }
    }
    return parts;
}

