def log_calls(fn: Callable) -> Callable:
    @functools.wraps(fn)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        arg_str = ', '.join([repr(a) for a in args] + [f'{k}={v!r}' for k, v in kwargs.items()])
        result = fn(*args, **kwargs)
        print(f'{fn.__name__}({arg_str}) -> {result!r}')
        return result
    return wrapper

#include <stdlib.h>

typedef struct {
    int *buf;
    int cap;
    int head;
    int tail;
    int size;
} RingBuf;

void ring_init(RingBuf *r, int capacity) {
    r->buf = malloc(capacity * sizeof(int));
    r->cap = capacity;
    r->head = r->tail = r->size = 0;
}

void ring_push(RingBuf *r, int val) {
    r->buf[r->tail] = val;
    r->tail = (r->tail + 1) % r->cap;
    if (r->size == r->cap)
        r->head = (r->head + 1) % r->cap;
    else
        r->size++;
}

int ring_pop(RingBuf *r, int *out) {
    if (r->size == 0) return 0;
    *out = r->buf[r->head];
    r->head = (r->head + 1) % r->cap;
    r->size--;
    return 1;
}

void ring_free(RingBuf *r) { free(r->buf); }
